        const service = new ActionRunRegistry()
        service.start()
        emit(runEvent('running'))
        emit({
            actionId: 'build', actionType: 'agent', context, interactionReady: true, phase: 'main',
            rootActionId: 'build', runId: 'run-1', status: 'running', type: 'action',
        })

